\begin{theorem}\label{thm:main}
Assume Assumption~\ref{ass:manifold}. Let $X$ be a connected smooth projective complex fourfold and let $D\subset X$ be a nonempty smooth connected reduced divisor. If $\sqrt[2]{(X,D)}$ is special, then
\begin{equation}\label{eq:target-group}
 G=\pi_1(X\setminus D,x)\big/\langle\!\langle\gamma^2\rangle\!\rangle
\end{equation}
contains an abelian subgroup of finite index. Here $\gamma$ is a positively oriented meridian about $D$, transported to $x\in X\setminus D$.
\end{theorem}

\begin{theorem}\label{thm:main}
There exist a smooth connected projective complex fourfold $X$ and a
simple abelian surface $A\subset X$ such that
\begin{enumerate}
\item $X$ has large fundamental group;
\item $\im\bigl(\pi_1(A)\to\pi_1(X)\bigr)\simeq\Z$.
\end{enumerate}
The universal cover $\widetilde X$ contains no positive-dimensional
compact complex analytic subvariety and is not Stein.
\end{theorem}

\begin{theorem}\label{thm:main}
Let $X$ be a compact connected K\"ahler manifold of positive complex
dimension. If every holomorphic map $\C\to X$ is constant, then $K_X$ is
ample. In particular, a positive tensor power of $K_X$ defines a
holomorphic embedding of $X$ into a complex projective space.
\end{theorem}

\begin{theorem}\label{end:canonical}
Assume Assumptions~\ref{hyp:campana}, \ref{hyp:mmp}, and
\ref{hyp:effective-abundance}. If \(W\) is a smooth compact
K\"ahler non-uniruled fourfold with \(a(W)=0\), then
\(\kappa(W,K_W)\ge0\).
\end{theorem}

\begin{corollary}[Projective abundance in the present setting]
\label{red:projective}
Under Assumption~\ref{hyp:campana}, a nef \(\Q\)-Cartier adjoint of a
normal projective log canonical pair over \(\C\), with effective rational
boundary, is semiample.
\end{corollary}

